CHUNK({"chunk":"P","module":"m4","topics":[{"id":"m4-paris-basics","title":"Paris Agreement: road to Paris, temperature goal and NDCs","short":"Paris Agreement basics","blurb":"From the UNFCCC and Kyoto through Copenhagen to COP21, the Article 2 temperature goal, NDCs and the ratchet mechanism, and India's NDC.","source":"Lecture W4 (Paris Agreement), pages 2–4, 8","tabs":[{"title":"Road to Paris and goal","html":"\n          <table class=\"tbl\">\n            <tbody>\n              <tr><td><b>UNFCCC 1992</b></td><td>Rio; <b>parent treaty</b></td></tr>\n              <tr><td><b>Kyoto 1997</b></td><td>Binding, developed only</td></tr>\n              <tr><td><b>Copenhagen 2009</b></td><td><b>Voluntary pledges</b> (became NDCs)</td></tr>\n              <tr><td><b>COP21 Paris, Dec 2015</b></td><td><b>196 parties</b>; in force <b>4 Nov 2016</b></td></tr>\n            </tbody>\n          </table>\n          <p><b>Article 2</b>: <b>well below 2°C</b>, pursuing <b>1.5°C</b>. 1.5°C pushed by <b>Small Island Developing States</b>; backed by <b>IPCC Special Report 2018</b> (reefs almost all lost at 2°C).</p>\n        "},{"title":"NDCs and India","html":"\n          <p>Kyoto <b>top-down</b> vs Paris <b>bottom-up</b> (<b>Nationally Determined Contributions</b>).</p>\n          <ul>\n            <li>NDC <b>every 5 years</b>, each more ambitious: <b>ratchet mechanism</b>.</li>\n            <li>Cover <b>mitigation, adaptation, finance</b>.</li>\n          </ul>\n          <div class=\"kv\">\n            <div><span>India 2030: non-fossil power</span><b>50%</b></div>\n            <div><span>Emissions intensity cut (vs 2005)</span><b>45%</b></div>\n            <div><span>Extra carbon sink</span><b>2.5–3 billion t CO₂e</b></div>\n          </div>\n        "}],"flashcards":[{"front":"Paris Agreement adopted at?","back":"<b>COP21</b>, December 2015, by <b>196 parties</b>."},{"front":"Paris entered into force?","back":"<b>4 November 2016</b>."},{"front":"Article 2 temperature goal?","back":"Well below <b>2°C</b>, pursuing <b>1.5°C</b>."}],"cardCount":8,"formulaCount":0},{"id":"m4-paris-pillars","title":"Paris Agreement: net zero, adaptation, finance and legal status","short":"Paris pillars, gaps","blurb":"Articles 4, 7 and 9, the transparency framework and Global Stocktake, whether Paris is binding, and the ambition, finance and loss-and-damage gaps.","source":"Lecture W4 (Paris Agreement), pages 4–8","tabs":[{"title":"Pillars and review","html":"\n          <table class=\"tbl\">\n            <tbody>\n              <tr><td><b>Article 4</b></td><td><b>Net zero</b> in second half of century (<b>balance, not zero</b>)</td></tr>\n              <tr><td><b>Article 7</b></td><td><b>Adaptation</b>, equal footing with mitigation</td></tr>\n              <tr><td><b>Article 9</b></td><td><b>Finance</b>: <b>USD 100 billion/yr</b>, <b>Green Climate Fund</b></td></tr>\n            </tbody>\n          </table>\n          <p><b>Enhanced Transparency Framework</b>: all report. <b>Global Stocktake</b> every <b>5 years</b>; first at <b>COP28 Dubai, 2023</b>.</p>\n        "},{"title":"Binding? Gaps","html":"\n          <ul>\n            <li>Agreement <b>binding</b>; <b>NDC targets not binding</b>. No penalty.</li>\n            <li>US withdrew <b>2020</b>, rejoined <b>2021</b>.</li>\n            <li><b>Ambition gap</b>: NDCs → <b>2.5–3°C</b>.</li>\n            <li><b>Finance gap</b>: USD 100 bn met only for <b>2022</b>.</li>\n            <li><b>Loss and Damage Fund</b>: set up <b>COP27 (2022)</b>, operational COP28.</li>\n          </ul>\n          <div class=\"note trap\">A <b>legally binding process</b> with <b>nationally determined substance</b>.</div>\n        "}],"flashcards":[{"front":"Paris article on net zero?","back":"<b>Article 4</b>: net zero in the second half of this century."},{"front":"Does net zero mean zero emissions?","back":"<b>No</b>; emissions equal removals."},{"front":"Paris article on adaptation?","back":"<b>Article 7</b>."}],"cardCount":7,"formulaCount":0}],"figures":[]});
